import {lessons,familyLesson,position,pawnFacts,theorySources} from './lessons.js';
import {guides} from './guides.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const side=['♔ 백','♚ 흑'];
const stepNames=['현재 구조','개선할 말','준비할 브레이크','공격 대상','유리한 교환','피해야 할 교환','원하는 포지션'];

export function miniBoard(c,pawnsOnly=true,label='대표 구조'){return `<div class="structure-board" role="img" aria-label="${esc(label)}. 백 폰 ${pawnFacts(c).white.pawns.join(', ')}. 흑 폰 ${pawnFacts(c).black.pawns.join(', ')}">${[8,7,6,5,4,3,2,1].flatMap((r,ri)=>[...'abcdefgh'].map((f,fi)=>{const x=c.get(f+r);return `<div class="mini-square ${(fi+r)%2===1?'mini-dark':''}">${x&&(!pawnsOnly||x.type==='p')?`<img src="./pieces/${x.color}${x.type.toUpperCase()}.svg" alt="" draggable="false">`:''}${fi===0?`<small>${r}</small>`:''}${ri===7?`<small class="mini-file">${f}</small>`:''}</div>`})).join('')}</div>`;}
function facts(c){const f=pawnFacts(c),format=a=>a.length?a.join(', '):'없음';return `<div class="pawn-facts"><div><b>백 폰</b><span>${format(f.white.pawns)}</span></div><div><b>흑 폰</b><span>${format(f.black.pawns)}</span></div><div><b>더블폰 파일</b><span>백 ${format(f.white.doubled)} / 흑 ${format(f.black.doubled)}</span></div><div><b>고립폰</b><span>백 ${format(f.white.isolated)} / 흑 ${format(f.black.isolated)}</span></div><div><b>열린 파일</b><span>${format(f.open)}</span></div><div><b>반열린 파일</b><span>백 ${format(f.semiWhite)} / 흑 ${format(f.semiBlack)}</span></div></div><p class="small muted">그림의 실제 폰 위치로 확인한 항목입니다. 더블폰·고립폰이 곧 나쁜 폰이라는 뜻은 아닙니다. 뒤처진 폰은 돌파 가능성과 상대 통제를 포함해 아래 해설에서 판단합니다.</p>`;}
export function mountLearning(g,loadLine){const lesson=lessons[g.id];const summary=lesson?`<div class="learning-intro"><div class="eyebrow">이 오프닝을 한 문장으로 설명하면?</div><p>${esc(lesson.summary)}</p><small>이 오프닝을 좋아할 가능성이 높은 플레이어</small><div class="taste-tags">${lesson.preferences.map(x=>`<span class="badge neutral">${esc(x)}</span>`).join('')}</div><div class="small muted">일반적인 성향입니다. 변형과 상대의 선택에 따라 달라집니다.</div></div>`:'';document.querySelector('.overview').insertAdjacentHTML('beforebegin',summary);
if(!lesson){mountData(g,loadLine);return;}
const plans=document.getElementById('plans');plans.insertAdjacentHTML('beforebegin',`<section id="strategy-learning"><div class="section-heading"><div><div class="eyebrow">OPENING → MIDDLEGAME</div><h2>수순을 계획으로 연결하기</h2></div><a href="#strategy-compare">오프닝 전략 비교 ↗</a></div><div class="learning-flow">${[['learn','수순'],['purpose','목적'],['pawn-structure','폰 구조'],['piece-roles','말의 역할'],['core-ideas','브레이크'],['attack-targets','공격 목표'],['counterplay','상대 반격'],['middlegame','미들게임']].map(([id,t],i)=>`<a href="#${id}" data-study-scroll="${id}"><small>0${i+1}</small>${t}</a>`).join('')}</div><label class="case-label" for="study-case">어떤 구조를 공부할까요?</label><select id="study-case" class="line-select">${lesson.cases.map((c,i)=>`<option value="${i}">${esc(c.label)}</option>`).join('')}</select><div id="case-content"></div></section>`);plans.querySelector('h2').textContent='기존 핵심 요약';
let caseIndex=0,pawnsOnly=true;const draw=()=>{const s=lesson.cases[caseIndex],c=position(s.line);document.getElementById('case-content').innerHTML=`<div class="case-scope"><span class="badge">${esc(s.label)}</span><p>${esc(s.scope)}</p></div><div id="purpose" class="lesson-section"><h3>01 · 오프닝의 목적</h3><p>${esc(s.purpose)}</p><p class="small muted">선택한 국면의 범위: ${esc(s.scope)}</p></div><div id="core-ideas" class="lesson-section"><h3>02 · 반복되는 핵심 아이디어</h3><div class="idea-list">${s.ideas.map((x,i)=>`<div><span>${i+1}</span><p>${esc(x)}</p></div>`).join('')}</div></div><div id="pawn-structure" class="lesson-section"><h3>03 · 전형적인 폰 구조</h3><div class="structure-layout"><div>${miniBoard(c,pawnsOnly,s.label)}<div class="diagram-controls"><button id="diagram-toggle" aria-pressed="${!pawnsOnly}">${pawnsOnly?'전체 기물 보기':'폰만 보기'}</button><button id="study-load" class="primary">메인 보드에서 연구</button></div><a class="small" href="https://lichess.org/analysis/standard/${c.fen().replace(/ /g,'_')}" target="_blank" rel="noopener">이 국면 분석판 열기 ↗</a></div><div><p>${esc(s.structure)}</p>${facts(c)}</div></div><details><summary>대표 국면까지의 합법 수순</summary><p class="line-text">${esc(c.pgn())}</p><p class="small muted">대표 예시이며 강제 수순·엔진 최선 수라는 뜻은 아닙니다. 구조가 바뀌면 계획도 다시 선택합니다.</p></details></div><div id="piece-roles" class="lesson-section"><h3>04 · 좋은 말 / 나쁜 말</h3><div class="plans">${s.pieces.map((x,i)=>`<div class="plan"><h4>${side[i]} · 구조와 말의 역할</h4><p>${esc(x)}</p></div>`).join('')}</div><p class="small muted">좋음·나쁨은 현재 폰 장벽과 활동을 기준으로 합니다. 폰 브레이크가 성공하면 평가가 달라집니다.</p></div><div id="attack-targets" class="lesson-section"><h3>05 · 어디를, 왜 공격할까요?</h3><div class="plans">${s.targets.map((x,i)=>`<div class="plan"><h4>${side[i]}의 표적</h4><p>${esc(x)}</p></div>`).join('')}</div></div><div id="counterplay" class="lesson-section"><h3>06 · 상대는 어떻게 무력화할까요?</h3><div class="counter-list">${s.counters.map(x=>`<div>${esc(x)}</div>`).join('')}</div></div><div id="middlegame" class="lesson-section"><h3>07 · 오프닝 다음, 미들게임 계획</h3><p class="small muted">우선순위의 흐름입니다. 매번 체크·잡기·위협을 먼저 확인하고, 아래 흐름을 강제 수순처럼 두지 않습니다.</p><div class="plan-flows">${s.plans.map((arr,i)=>`<div class="plan-flow"><h4>${side[i]}의 계획</h4><ol>${arr.map((x,j)=>`<li><small>${stepNames[j]}</small><span>${esc(x)}</span></li>`).join('')}</ol></div>`).join('')}</div><details><summary>실전에서 스스로 판단하기</summary><p>① 지금 어떤 폰 브레이크가 가능한가요? ② 가장 활동이 나쁜 말은 무엇인가요? ③ 상대가 먼저 노리는 표적은 무엇인가요? ④ 교환 후 어느 쪽의 폰 약점이 더 중요해지나요?</p><p>선택한 국면을 메인 보드로 보내고 자유 탐색에서 양쪽 수를 직접 두며 확인하세요.</p></details></div><div class="small muted theory-note">수순·구조를 구분해 새로 작성한 전략 설명입니다. 계열·구조 참고: ${lesson.references.map(([t,u])=>`<a href="${u}" target="_blank" rel="noopener">${esc(t)}</a>`).join(' · ')}. 숫자 평가·승률을 제공하지 않습니다.</div>`;
document.getElementById('diagram-toggle').onclick=()=>{pawnsOnly=!pawnsOnly;draw()};document.getElementById('study-load').onclick=()=>loadLine(s.line,s.label);};document.getElementById('study-case').onchange=e=>{caseIndex=+e.target.value;draw()};draw();
document.querySelectorAll('[data-study-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.studyScroll)?.scrollIntoView({behavior:'smooth'})});const toc=document.querySelector('.toc');toc.querySelector('[data-scroll="plans"]').insertAdjacentHTML('beforebegin','<a href="#strategy-learning" data-study-scroll="strategy-learning">구조와 전략 학습</a><a href="#middlegame" data-study-scroll="middlegame">미들게임 계획</a>');toc.querySelectorAll('[data-study-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.studyScroll)?.scrollIntoView({behavior:'smooth'})});}
function mountData(g,loadLine){const family=familyLesson(g),c=position(g.line);document.querySelector('#learn').insertAdjacentHTML('afterend',`<section class="dataset-study"><h2>이 수순에서 실제로 만들어진 구조</h2><div class="structure-layout"><div>${miniBoard(c,true,g.name)}<button id="data-load" class="primary wide">마지막 국면에서 연구</button></div><div>${facts(c)}<p>${family?`가까운 학습 계열: <a href="#opening/${family.id}">${esc(guides.find(x=>x.id===family.id).name)}</a>`:'전개·중앙·킹 안전의 원칙으로 현재 구조를 먼저 읽어 보세요.'}</p><p class="small muted">전체 수순 데이터의 개별 희귀 변형에는 편집자가 작성한 전용 이론 해설이 없습니다. 가까운 계열의 계획은 위 가이드에서 구조를 대조해 적용하세요. 이름이 비슷해도 폰 배치와 캐슬링이 다르면 같은 계획을 그대로 적용하지 않습니다.</p><a href="#strategy-compare">학습 가이드끼리 전략 비교 →</a></div></div></section>`);document.getElementById('data-load').onclick=()=>loadLine(g.line,g.name);}
let left='french',right='caro';
export function strategyCompare(){const main=document.getElementById('main'),draw=()=>{const a=lessons[left],b=lessons[right],names=[left,right].map(id=>guides.find(g=>g.id===id).name),sides=[a.cases[0],b.cases[0]];main.innerHTML=`<div class="eyebrow">COMPARE THE PLANS</div><h1>오프닝 전략 비교</h1><p class="subtitle">같은 첫 수에서 다른 미들게임으로. 순위 대신 목적·구조·말·돌파를 비교하세요.</p><div class="compare-presets">${[['open-game','sicilian','e5 vs 시실리안'],['french','caro','프렌치 vs 카로칸'],['kings-indian','grunfeld','킹스 인디언 vs 그륀펠드'],['italian','ruy','이탈리안 vs 루이 로페즈'],['sicilian-dragon','sicilian-accelerated','드래곤 vs 액셀러레이티드'],['french-advance','french-exchange','프렌치 사슬 vs 교환형']].map(([l,r,t])=>`<button data-left="${l}" data-right="${r}">${t}</button>`).join('')}</div><div class="compare-pickers">${[left,right].map((id,i)=>`<label>${i?'두 번째':'첫 번째'} 오프닝<select id="compare-${i}" class="line-select">${guides.map(g=>`<option value="${g.id}" ${g.id===id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label>`).join('')}</div><div class="comparison-diagrams">${sides.map((s,i)=>`<div><h3><a href="#opening/${i?right:left}">${esc(names[i])} ↗</a></h3><p>${esc(i?b.summary:a.summary)}</p>${miniBoard(position(s.line),true,names[i])}<p class="small muted">${esc(i?b.scope:a.scope)}</p></div>`).join('')}</div><div class="table-wrap strategy-table"><table><thead><tr><th>판단 기준</th>${names.map(n=>`<th>${esc(n)}</th>`).join('')}</tr></thead><tbody>${[['목적',s=>s.purpose],['폰 구조',s=>s.structure],['말의 역할',s=>s.pieces.join('\n\n')],['브레이크와 핵심 아이디어',s=>s.ideas.join('\n\n')],['공격 대상',s=>s.targets.join('\n\n')],['상대의 반격',s=>s.counters.join('\n\n')],['백의 미들게임',s=>s.plans[0].join(' → ')],['흑의 미들게임',s=>s.plans[1].join(' → ')]].map(([t,fn])=>`<tr><th>${t}</th>${sides.map(s=>`<td>${esc(fn(s))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small muted" style="margin-top:18px">각 가이드의 대표 수순끼리 비교합니다. 각 오프닝 내부의 다른 구조는 해당 페이지의 구조 선택에서 확인하세요.</p>`;document.querySelectorAll('[data-left]').forEach(x=>x.onclick=()=>{left=x.dataset.left;right=x.dataset.right;draw()});document.getElementById('compare-0').onchange=e=>{left=e.target.value;draw()};document.getElementById('compare-1').onchange=e=>{right=e.target.value;draw()};};draw();}
export function appendTheorySources(){document.getElementById('main').insertAdjacentHTML('beforeend',`<div class="source-card"><h3>전략 학습 · 구조 대조 자료</h3><p>대표 오프닝의 일반적인 아이디어를 아래 자료와 대조했습니다. 설명은 자체 작성했으며, 출처별 입문 티어와 전략 이론을 분리합니다. 모든 예시 수순·보드는 합법성 검증을 거쳤습니다.</p><div class="source-inline">${theorySources.map(([t,u])=>`<a href="${u}" target="_blank" rel="noopener">${esc(t)}</a>`).join('')}</div></div>`);}
